function safeWaitUntil(ctx, promise) {
	if (ctx && typeof ctx.waitUntil === "function") {
		try {
			ctx.waitUntil(promise);
		} catch (e) {}
	} else if (promise && typeof promise.catch === "function") {
		promise.catch(() => {});
	}
}

