/* کشور یک آی‌پی: check-host.net اول، بعد پشتیبان‌ها */
function sabiHostIsIp(h) {
	const x = String(h || "").trim();
	if (!x) return false;
	if (x.charAt(0) === "[" && x.indexOf("]") > 0) return true;
	if (x.indexOf(":") >= 0) return true;
	let dots = 0;
	for (let i = 0; i < x.length; i++) { const c = x.charCodeAt(i); if (c === 46) { dots++; continue; } if (c < 48 || c > 57) return false; }
	return dots === 3;
}
async function sabiGeoOne(ip, env) {
	const h = String(ip || "").trim();
	if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(h)) return "";
	if (SABI_GEO_MEM.has(h)) return SABI_GEO_MEM.get(h);
	const db = await sabiGeoDbLoad(env);
	const hit = db[h];
	if (hit && hit.c && (Date.now() - (hit.at || 0)) < 604800000) { SABI_GEO_MEM.set(h, hit.c); return hit.c; }
	let cc = "";
	if (SABI_CH_GEO_FAIL < 3) {
		const html = await sabiGeoHttp("https://check-host.net/ip-info?host=" + encodeURIComponent(h), 5000);
		if (html) {
			const m = /<strong>([^<]{2,60})<\/strong>\s*\(([A-Za-z]{2})\)/.exec(html);
			if (m && m[2]) cc = String(m[2]).toUpperCase();
		}
		if (!cc) SABI_CH_GEO_FAIL++;
	}
	if (!cc) { try { const t = await sabiGeoHttp("https://api.country.is/" + h, 4000); if (t) { const j = JSON.parse(t); if (j && j.country) cc = String(j.country).toUpperCase(); } } catch (e) { } }
	if (!cc) { try { const t = await sabiGeoHttp("https://ipwho.is/" + h + "?fields=country_code", 4000); if (t) { const j = JSON.parse(t); if (j && j.country_code) cc = String(j.country_code).toUpperCase(); } } catch (e) { } }
	if (!cc) {
		try {
			const ctl = new AbortController();
			const t = setTimeout(function () { try { ctl.abort(); } catch (e) { } }, 4000);
			const r = await fetch("http://ip-api.com/json/" + h + "?fields=countryCode", { signal: ctl.signal, headers: { "User-Agent": "Mozilla/5.0" } });
			clearTimeout(t);
			if (r && r.ok) { const j = await r.json(); if (j && j.countryCode) cc = String(j.countryCode).toUpperCase(); }
		} catch (e) { }
	}
	if (/^[A-Z]{2}$/.test(cc)) {
		SABI_GEO_MEM.set(h, cc);
		db[h] = { c: cc, at: Date.now() };
		SABI_GEO_DB = db; SABI_GEO_DB_AT = Date.now(); SABI_GEO_DIRTY++;
		if (SABI_GEO_DIRTY >= 25) await sabiGeoDbSave(env);
	}
	return cc;
}
async function sabiGeoBatch(ipsArr, env) {
	const out = {};
	const list = (Array.isArray(ipsArr) ? ipsArr : []).map(function (x) { return String(x || "").trim(); }).filter(function (x) { return /^\d{1,3}(\.\d{1,3}){3}$/.test(x); }).slice(0, 160);
	for (let i = 0; i < list.length; i += 8) {
		const chunk = list.slice(i, i + 8);
		const rs = await Promise.all(chunk.map(function (h) { return sabiGeoOne(h, env); }));
		chunk.forEach(function (h, k) { if (rs[k]) out[h] = rs[k]; });
	}
	if (SABI_GEO_DIRTY > 0) await sabiGeoDbSave(env);
	return out;
}
/* منبع آی‌پی تمیز (آدرس base64 است تا در کد قابل‌شناسایی نباشد) */
