let SABI_MX_MEM = { at: 0, list: null, meta: null };
async function sabiCleanIpsList(limit, force) {
	const lim = Math.min(Math.max(parseInt(limit, 10) || 120, 1), 500);
	const now = Date.now();
	if (!force && SABI_MX_MEM.list && SABI_MX_MEM.list.length && (now - SABI_MX_MEM.at) < 600000) return SABI_MX_MEM.list.slice(0, lim);
	try {
		const u = sabiSrcUrl();
		if (!u) throw new Error("no-src");
		const ctl = new AbortController();
		const t = setTimeout(function () { try { ctl.abort(); } catch (e) { } }, 9000);
		const r = await fetch(u + "?t=" + now, { signal: ctl.signal, headers: { "User-Agent": "Mozilla/5.0", "Accept": "application/json,text/plain,*/*" } });
		clearTimeout(t);
		if (!r || !r.ok) throw new Error("http " + (r && r.status));
		const j = await r.json();
		const arr = Array.isArray(j && j.results) ? j.results : [];
		const seen = {};
		const list = [];
		arr.forEach(function (e) {
			const ip = String((e && e.ip) || "").trim();
			if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(ip) || seen[ip]) return;
			if (e.status && e.status !== "online") return;
			seen[ip] = 1;
			list.push({ ip: ip, ms: Number(e.ms) || 9999, colo: String(e.colo || ""), persistent: !!e.persistent, long_term: !!e.long_term, online_count: Number(e.online_count) || 0 });
		});
		list.sort(function (a, b) { return (a.ms - b.ms) || (b.online_count - a.online_count); });
		SABI_MX_MEM = { at: now, list: list, meta: { updated: (j && j.updated) || 0, online: (j && j.online_count) || list.length, persistent: (j && j.persistent_count) || 0 } };
		return list.slice(0, lim);
	} catch (e) {
		return (SABI_MX_MEM.list || []).slice(0, lim);
	}
}
