async function sabiSaveIpTestResults(results, env) {
	try {
		const nowT = Date.now();
		let cacheJ = {};
		const rowT = await env.DB.prepare("SELECT value FROM settings WHERE key = 'sabi_ip_test_cache'").first();
		if (rowT && rowT.value) { try { cacheJ = JSON.parse(rowT.value) || {}; } catch (e) { cacheJ = {}; } }
		results.forEach(function (r) {
			const prev = cacheJ[r.ip] || {};
			cacheJ[r.ip] = { ok: r.ok, at: nowT, cc: r.cc || prev.cc || "" };
		});
		const keysT = Object.keys(cacheJ);
		if (keysT.length > 400) {
			keysT.sort(function (a, b) { return (cacheJ[a].at || 0) - (cacheJ[b].at || 0); });
			keysT.slice(0, keysT.length - 400).forEach(function (k) { delete cacheJ[k]; });
		}
		await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('sabi_ip_test_cache', ?)").bind(JSON.stringify(cacheJ)).run();
		SABI_IP_TEST_MEM = { at: 0, bad: null, cc: null };
	} catch (e) { }
}
