/* lazy getter — UPDATE_REPO_WORKER بعد از این خط تعریف می‌شود؛ تابع hoisted است و خطای TDZ نمی‌دهد */
function sabiRepoJsonUrl() { return "https://raw.githubusercontent.com/" + UPDATE_REPO_WORKER + "/main/live-ips.json"; }
let SABI_REPO_IPS_MEM = { at: 0, ips: null };
let SABI_EXT_IPS_MEM = { at: 0, url: "", ips: null };
function sabiParseIpsFromSub(text) {
	try {
		let t = String(text || "");
		if (!t) return [];
		if (t.indexOf("://") < 0) {
			try {
				const b64 = t.replace(/[^A-Za-z0-9+/=]/g, "");
				if (b64.length > 40) t = decodeURIComponent(escape(atob(b64)));
			} catch (e) { }
		}
		const ips = [];
		const seen = {};
		const pushIp = function (x) {
			x = String(x || "").trim();
			if (/^\d{1,3}(\.\d{1,3}){3}$/.test(x) && x.split(".").every(function (n) { return Number(n) <= 255; }) && !seen[x]) {
				seen[x] = 1;
				ips.push(x);
			}
		};
		const reLink = /(vless|trojan|ss|vmess):\/\/([^\s"'<]+)/g;
		let m;
		while ((m = reLink.exec(t)) !== null) {
			const proto = m[1];
			const rest = m[2];
			if (proto === "vmess") {
				try {
					const j = JSON.parse(decodeURIComponent(escape(atob(rest.split("?")[0]))));
					pushIp(j && j.add);
				} catch (e) { }
				continue;
			}
			const at = rest.lastIndexOf("@");
			if (at < 0) continue;
			let addr = rest.slice(at + 1).split(/[/?#]/)[0];
			if (addr.indexOf("[") >= 0) continue;
			pushIp(addr.split(":")[0]);
		}
		return ips.slice(0, 60);
	} catch (e) { return []; }
}
