function sabiFaNameToCc(name) {
	const n = String(name || "").replace(/[\u200c\u200d\u200e\u200f]/g, " ").replace(/\s+/g, " ").trim();
	if (!n) return "";
	if (SABI_FA_CC_MAP[n]) return SABI_FA_CC_MAP[n];
	let best = "", bestLen = 0;
	for (const k in SABI_FA_CC_MAP) {
		if (n.indexOf(k) >= 0 && k.length > bestLen) { best = SABI_FA_CC_MAP[k]; bestLen = k.length; }
	}
	return best;
}

function sabiFaParseIpRepo(text) {
	const out = [];
	const seen = {};
	const src = String(text || "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n");
	const lines = src.split("\n");
	for (let i = 0; i < lines.length; i++) {
		let line = String(lines[i] || "").trim();
		if (!line) continue;
		if (/^(#|\/\/|;|<!--|\*)/.test(line)) continue;
		line = line.replace(/<!--[\s\S]*?-->/g, " ").replace(/\s+#.*$/, " ").trim();
		if (!line) continue;
		const m = line.match(/(\d{1,3}(?:\.\d{1,3}){3})(?::\d{2,5})?([\s\S]*)$/);
		if (!m) continue;
		const ip = m[1];
		const octs = ip.split(".");
		let ok = true;
		for (let k = 0; k < 4; k++) { const o = Number(octs[k]); if (!(o >= 0 && o <= 255)) { ok = false; break; } }
		if (!ok) continue;
		let name = String(m[2] || "");
		if (!SABI_FA_TEXT_RE.test(name)) {
			name = String(line.slice(0, line.indexOf(ip)) || "");
			if (!SABI_FA_TEXT_RE.test(name)) continue;
		}
		name = name.replace(/^[\s\u{1F1E6}-\u{1F1FF}\u{1F3F3}\u{FE0F}\u{1F308}\u{1F3F4}\u{E0067}-\u{E007F}]+/u, "")
			.replace(/^[\s\-–—:|,،=•*_.)\]]+/, "")
			.replace(/[\u200c\u200d]/g, " ")
			.replace(/[\s\-–—:|,،=•*_(\[]+$/, "")
			.replace(/\s+/g, " ")
			.trim();
		if (!name || !SABI_FA_TEXT_RE.test(name)) continue;
		if (name.length > 40) name = name.slice(0, 40).trim();
		if (seen[ip]) continue;
		seen[ip] = 1;
		out.push({ ip: ip, name: name, cc: sabiFaNameToCc(name) });
		if (out.length >= SABI_FA_REPO.max) break;
	}
	return out;
}

