let SABI_OPEN_IPS_MEM = { at: 0, key: "", ips: null };
async function sabiResolveDomainA(domain, ms) {
	const out = [];
	const endpoints = ["https://1.1.1.1/dns-query", "https://cloudflare-dns.com/dns-query", "https://8.8.8.8/resolve", "https://dns.google/resolve"];
	for (let i = 0; i < endpoints.length && out.length === 0; i++) {
		try {
			const r = await sabiDohJson(endpoints[i], String(domain).trim(), "A", ms || 4500);
			if (!r.ok || !r.json) continue;
			(r.json.Answer || []).forEach(function (a) {
				const d = String((a && a.data) || "").trim();
				if (/^\d{1,3}(\.\d{1,3}){3}$/.test(d) && out.indexOf(d) < 0) out.push(d);
			});
		} catch (e) { }
	}
	return out;
}
async function sabiOpenDomainIps(domains, cfOnly, force) {
	const list = ((domains && domains.length) ? domains : SABI_OPEN_DOMAINS_DEFAULT)
		.map(function (d) { return String(d || "").trim().toLowerCase(); })
		.filter(function (d) { return d && d.indexOf(".") > 0; }).slice(0, 20);
	if (!list.length) return [];
	const key = list.join(",") + "|" + (cfOnly ? "cf" : "all");
	const now = Date.now();
	if (!force && SABI_OPEN_IPS_MEM.ips && SABI_OPEN_IPS_MEM.key === key && (now - SABI_OPEN_IPS_MEM.at) < 3600000) return SABI_OPEN_IPS_MEM.ips;
	try { await sabiCfRangesRefresh(); } catch (e) { }
	let rows = [];
	try { rows = await Promise.all(list.map(function (d) { return sabiResolveDomainA(d, 4500).then(function (ips) { return { domain: d, ips: ips }; }); })); } catch (e) { rows = []; }
	const out = [];
	const seen = {};
	rows.forEach(function (r) {
		(r.ips || []).forEach(function (ip) {
			if (seen[ip]) return;
			let isCf = false;
			try { isCf = sabiIpInCf(ip); } catch (e) { }
			if (cfOnly && !isCf) return;
			seen[ip] = 1;
			out.push({ ip: ip, domain: r.domain, cf: !!isCf });
		});
	});
	out.sort(function (a, b) { return (b.cf ? 1 : 0) - (a.cf ? 1 : 0); });
	SABI_OPEN_IPS_MEM = { at: now, key: key, ips: out };
	return out;
}

function sabiNormFm(s) { return String(s || "").replace(/\s+/g, ""); }
function sabiFmFor(userFm, profile) {
	/* v1.0.5: ماسک کاربر اگر «دست‌نخورده/شناخته‌شده» باشد با پروفایل سراسری جایگزین
	   می‌شود (heavy/light/off)؛ JSON دلخواه کاربر هرگز دست‌نخورده می‌ماند. */
	if (sabiFmIsKnown(userFm)) return sabiFmForProfile(profile || "heavy");
	return String(userFm);
}
/* v1.0.5 FRAG-BOOST: تقویت مقدار فرگمنت هنگام ساخت اشتراک —
   بازهٔ طول ×0.6 تا ×1.5 (سقف ۱۵۰۰) و بازهٔ فاصله ×0.75 تا ×2 (سقف ۱۰۰).
   نتیجه: پکت‌های بیشتر و پخش زمانی گسترده‌تر => عبور قوی‌تر از فیلترینگ. */
function sabiBoostRange(str, loMul, hiMul, loCap, hiCap) {
	const s = String(str || "").trim();
	if (!s) return "";
	const parts = s.split("-");
	if (parts.length >= 2) {
		const a = parseFloat(parts[0]);
		const b = parseFloat(parts[1]);
		if (!isFinite(a) || !isFinite(b) || a <= 0 || b <= 0) return s;
		const lo = Math.max(loCap, Math.floor(Math.min(a, b) * loMul));
		const hi = Math.min(hiCap, Math.max(lo + 1, Math.ceil(Math.max(a, b) * hiMul)));
		return lo + "-" + hi;
	}
	const n = parseFloat(s);
	if (!isFinite(n) || n <= 0) return s;
	const lo2 = Math.max(loCap, Math.floor(n * loMul));
	const hi2 = Math.min(hiCap, Math.max(lo2 + 1, Math.ceil(n * hiMul)));
	return lo2 + "-" + hi2;
}
function sabiFragBoost(len, int) {
	return {
		len: sabiBoostRange(len, 0.6, 1.5, 1, 1500),
		int: sabiBoostRange(int, 0.75, 2, 1, 100)
	};
}

function sabiShuffle(arr) {
	const a = (arr || []).slice();
	for (let i = a.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		const t = a[i]; a[i] = a[j]; a[j] = t;
	}
	return a;
}

const GLOBAL_TRAFFIC_CACHE = new Map();
const ACTIVE_CONNECTIONS_COUNT = new Map();
const GLOBAL_ACTIVE_USER_SOCKETS = new Map();
function sabiRegisterActiveUserSocket(username, uuid, sockEntry) {
	const keys = [String(username || "").toLowerCase(), String(uuid || "").toLowerCase()].filter(Boolean);
	for (const k of keys) {
		let set = GLOBAL_ACTIVE_USER_SOCKETS.get(k);
		if (!set) { set = new Set(); GLOBAL_ACTIVE_USER_SOCKETS.set(k, set); }
		set.add(sockEntry);
	}
}
function sabiUnregisterActiveUserSocket(username, uuid, sockEntry) {
	const keys = [String(username || "").toLowerCase(), String(uuid || "").toLowerCase()].filter(Boolean);
	for (const k of keys) {
		const set = GLOBAL_ACTIVE_USER_SOCKETS.get(k);
		if (set) {
			set.delete(sockEntry);
			if (set.size === 0) GLOBAL_ACTIVE_USER_SOCKETS.delete(k);
		}
	}
}
function sabiKillUserSocketsImmediate(username, uuid) {
	const keys = [String(username || "").toLowerCase(), String(uuid || "").toLowerCase()].filter(Boolean);
	for (const k of keys) {
		const set = GLOBAL_ACTIVE_USER_SOCKETS.get(k);
		if (!set) continue;
		for (const entry of Array.from(set)) {
			try { if (entry.remote && entry.remote.socket) entry.remote.socket.close(); } catch (_) {}
			try { if (entry.ws) entry.ws.close(1008, "User disabled or deleted"); } catch (_) {}
		}
		GLOBAL_ACTIVE_USER_SOCKETS.delete(k);
	}
	if (username) {
		ACTIVE_CONNECTIONS_COUNT.delete(username);
		GLOBAL_ACTIVE_IPS.delete(username);
	}
}
const GLOBAL_ACTIVE_IPS = new Map();
