async function ensureTlsOnlyPorts(env, ctx) {
	/* One-time normalization: stored user ports become TLS-only (like the default panel behavior).
	   Non-TLS ports (80/8080/...) cannot be encrypted by Cloudflare, so they are removed from the
	   database itself. If a user ends up with no TLS port, they get 443. Never breaks requests. */
	/* پنل هرگز پورت‌های کاربر را بازنویسی نمی‌کند — هر پورتی که وارد شده باشد
	   (TLS یا غیرTLS) سر جایش می‌ماند و برای پورت غیرTLS لینک security=none ساخته می‌شود
	   مهاجرت «فقط‌TLS‌سازی» برای همیشه غیرفعال شد. */
	if (true) return;
	if (localPortsTlsMigrated) return;
	try {
		const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'ports_tls_only_migrated'").first();
		if (row && row.value === '1') { localPortsTlsMigrated = true; return; }
		const rows = (await env.DB.prepare("SELECT username, port FROM users").all()).results || [];
		const TLS_OK = ["443", "2053", "2083", "2087", "2096", "8443"];
		const stmts = [];
		for (const r of rows) {
			const ports = String(r.port || "443").split(",").map((p) => p.trim()).filter((p) => p.length > 0);
			const keep = ports.filter((p) => TLS_OK.indexOf(p) >= 0);
			const next = (keep.length > 0 ? keep : ["443"]).join(",");
			if (next !== String(r.port || "")) {
				stmts.push(env.DB.prepare("UPDATE users SET port = ?, tls = 'on' WHERE username = ?").bind(next, r.username));
			}
		}
		stmts.push(env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('ports_tls_only_migrated', '1')"));
		await env.DB.batch(stmts);
		localPortsTlsMigrated = true;
	} catch (e) { }
}

async function checkAutoResets(env, ctx) {
	const now = Date.now();
	if (now - localLastAutoResetCheck < 3600000) return;
	try {
		const cache = caches.default;
		const cacheReq = new Request("https://internal.sabi/auto_reset");
		if (await cache.match(cacheReq)) return;
		const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'last_auto_reset_check'").first();
		const dbLastCheck = row ? parseInt(row.value) || 0 : 0;
		if (now - dbLastCheck < 3600000) {
			localLastAutoResetCheck = dbLastCheck;
			const ttl = Math.floor((3600000 - (now - dbLastCheck)) / 1000);
			if (ttl > 0) safeWaitUntil(ctx, cache.put(cacheReq, new Response("1", { headers: { "Cache-Control": `max-age=${ttl}` } })));
			return;
		}
		await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('last_auto_reset_check', ?)").bind(String(now)).run();
		localLastAutoResetCheck = now;
		safeWaitUntil(ctx, cache.put(cacheReq, new Response("1", { headers: { "Cache-Control": "max-age=3600" } })));
		const todayUtc = Math.floor(now / 86400000) * 86400000;
		await env.DB.prepare(`UPDATE users SET used_gb = 0, is_active = 1, last_reset_vol_time = ? WHERE auto_reset_vol_days > 0 AND ? >= (last_reset_vol_time + (auto_reset_vol_days * 86400000))`).bind(todayUtc, todayUtc).run();
		await env.DB.prepare(`UPDATE users SET used_req = 0, is_active = 1, last_reset_req_time = ? WHERE auto_reset_req_days > 0 AND ? >= (last_reset_req_time + (auto_reset_req_days * 86400000))`).bind(todayUtc, todayUtc).run();
	} catch (e) { }
}
