function getRandomIps(cachedIpsData, operator, count) {
	let availableIps = [];
	Object.values(cachedIpsData).forEach((ips) => (availableIps = availableIps.concat(ips)));
	availableIps = [...new Set(availableIps)];
	if (availableIps.length === 0) return [];
	if (count >= availableIps.length) return availableIps;
	/* v1.0.5: استخر از قبل بر اساس پینگ مرتب است — فقط از بخش سریع بردار
	   و داخل همان بخش درهم بریز تا هم کیفیت بالا بماند هم آی‌پی‌ها بچرخند */
	const headSize = Math.min(availableIps.length, Math.max(count * 3, count + 10));
	const shuffled = availableIps.slice(0, headSize);
	for (let i = shuffled.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
	}
	return shuffled.slice(0, count);
}
