		// ================= LIVE IP / PROXY SCANNER API =================
		function ipToInt(ip) {
			const p = String(ip).split(".");
			return (((+p[0] << 24) + (+p[1] << 16) + (+p[2] << 8) + (+p[3])) >>> 0);
		}
		function intToIp(n) {
			return [((n >>> 24) & 255), ((n >>> 16) & 255), ((n >>> 8) & 255), (n & 255)].join(".");
		}
		function randomIpsFromCidr(cidr, count) {
			const out = [];
			const parts = String(cidr).split("/");
			const base = parts[0];
			let bits = parseInt(parts[1] || "32", 10);
			if (isNaN(bits) || bits < 8 || bits > 32) bits = 24;
			const size = Math.pow(2, 32 - bits);
			if (size < 4) return [base];
			const start = ipToInt(base);
			const seen = {};
			let tries = 0;
			while (out.length < count && tries < count * 15) {
				tries++;
				const off = 1 + Math.floor(Math.random() * (size - 2));
				const ip = intToIp((start + off) >>> 0);
				if (!seen[ip]) { seen[ip] = 1; out.push(ip); }
			}
			return out;
		}
		const CDN_FALLBACK = {
			cf: ["104.16.0.0/13", "172.64.0.0/13", "162.158.0.0/15", "188.114.96.0/20", "197.234.240.0/22", "172.66.0.0/16"],
			aws: ["13.32.0.0/15", "52.222.128.0/17", "99.84.0.0/16", "205.251.192.0/19", "108.156.0.0/14", "130.176.0.0/17"],
			fastly: ["151.101.0.0/16", "199.232.0.0/16", "146.75.0.0/16", "199.116.208.0/21"],
			google: ["142.250.0.0/15", "172.217.0.0/16", "216.58.192.0/19", "74.125.0.0/16"],
			azure: ["13.64.0.0/11", "20.0.0.0/11", "104.40.0.0/13", "40.64.0.0/10"]
		};
		/* fetch with a hard timeout - one hanging host can never stall the scan */
		/* Fetch + parse a CDN range file under a HARD deadline. The work is raced
		   against a timer, so a source that hangs forever can never stall the scan
		   (abort alone is not enough - a slow body would still run past it). */
		async function cdnFetchJson(url, ms, parse) {
			const deadline = ms || 6000;
			let timer = null;
			const guard = new Promise(function (resolve) {
				timer = setTimeout(function () { resolve({ __timeout: true }); }, deadline);
			});
			const work = (async function () {
				try {
					const ctl = (typeof AbortController !== "undefined") ? new AbortController() : null;
					const r = await fetch(url, Object.assign(
						{ headers: { "User-Agent": "Mozilla/5.0" } },
						ctl ? { signal: ctl.signal } : {}
					));
					if (!r || !r.ok) return null;
					const txt = await r.text();
					/* nothing this big can be JSON.parse()d inside a Worker's CPU
					   budget - bail out early and let the static ranges take over */
					if (!txt || txt.length > 1500000) return null;
					return parse(JSON.parse(txt));
				} catch (e) {
					return null;
				}
			})();
			try {
				const out = await Promise.race([work, guard]);
				return (out && out.__timeout) ? null : out;
			} finally {
				clearTimeout(timer);
			}
		}

		/* Returns { ranges: {provider: [cidr]}, status: {provider: "live"|"fallback"|"fail"} }.
		   Never throws - a total network failure still yields the built-in ranges. */
		async function fetchCdnRanges(providers) {
			const ranges = {};
			const status = {};
			providers.forEach(function (p) { ranges[p] = []; status[p] = "fail"; });

			const jobs = [];
			if (providers.indexOf("cf") >= 0) jobs.push(cdnFetchJson(
				"https://api.cloudflare.com/client/v4/ips", 6000,
				function (j) { return (j && j.result && j.result.ipv4_cidrs) ? j.result.ipv4_cidrs.slice() : null; }
			).then(function (v) { if (v && v.length) { ranges.cf = v; status.cf = "live"; } }));

			/* Official CloudFront-only list: 4 KB instead of the 2.7 MB
			   ip-ranges.json. Parsing that monster inside a Worker blew the CPU
			   budget every single time, which is why the scanner used to fail at
			   random whenever AWS was selected. */
			if (providers.indexOf("aws") >= 0) jobs.push(cdnFetchJson(
				"https://d7uri8nf7uskq.cloudfront.net/tools/list-cloudfront-ips", 7000,
				function (j) {
					if (!j) return null;
					const out = [];
					const keys = ["CLOUDFRONT_GLOBAL_IP_LIST", "CLOUDFRONT_REGIONAL_EDGE_IP_LIST"];
					for (const k of keys) {
						const arr = j[k];
						if (!arr || !arr.length) continue;
						for (const c of arr) if (c) out.push(c);
					}
					return out.length ? out : null;
				}
			).then(function (v) { if (v && v.length) { ranges.aws = v; status.aws = "live"; } }));

			if (providers.indexOf("fastly") >= 0) jobs.push(cdnFetchJson(
				"https://api.fastly.com/public-ip-list", 6000,
				function (j) { return (j && j.addresses && j.addresses.length) ? j.addresses.slice() : null; }
			).then(function (v) { if (v && v.length) { ranges.fastly = v; status.fastly = "live"; } }));

			if (providers.indexOf("google") >= 0) jobs.push(cdnFetchJson(
				"https://www.gstatic.com/ipranges/goog.json", 6000,
				function (j) {
					if (!j || !j.prefixes) return null;
					const out = j.prefixes.map(function (x) { return x && x.ipv4Prefix; }).filter(Boolean);
					return out.length ? out : null;
				}
			).then(function (v) { if (v && v.length) { ranges.google = v; status.google = "live"; } }));

			/* azure publishes no single plain range file - its static list is used */
			if (providers.indexOf("azure") >= 0) status.azure = "static";

			try { await Promise.all(jobs); } catch (e) { }

			providers.forEach(function (p) {
				if (ranges[p] && ranges[p].length) return;
				ranges[p] = (CDN_FALLBACK[p] || []).slice();
				if (ranges[p].length && status[p] !== "static") status[p] = "fallback";
			});
			return { ranges: ranges, status: status };
		}
		if (url.pathname === "/api/cf-ranges" && request.method === "GET") {
			/* GIANT: تمام رنج‌های کلودفلر — رسمی + جدید تأییدشده + لایهٔ زندهٔ BGP جهانی */
			try {
				const session = await DbService.getSession(request, env);
				if (!session || !session.is_admin) return new Response(JSON.stringify({ error: "دسترسی مجاز نیست" }), { status: 403, headers: { "Content-Type": "application/json; charset=utf-8" } });
				try { await sabiCfRangesRefresh(); } catch (e) { }
				const official = (SABI_CF_RANGE_CACHE.list && SABI_CF_RANGE_CACHE.list.length) ? SABI_CF_RANGE_CACHE.list : SABI_CF_RANGES.slice();
				let bgp = [];
				try { bgp = await sabiBgpCfRanges(env); } catch (e) { }
				return new Response(JSON.stringify({ success: true, official: official, extras: SABI_CF_EXTRA_RANGES, bgp: bgp, bgp_count: bgp.length, at: Date.now() }), { headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });
			} catch (e) {
				return new Response(JSON.stringify({ success: false, official: SABI_CF_RANGES, extras: SABI_CF_EXTRA_RANGES, bgp: [] }), { headers: { "Content-Type": "application/json; charset=utf-8" } });
			}
		}
		if (url.pathname === "/api/geo-batch" && request.method === "POST") {
			/* GIANT: پرچم/کشور دسته‌ای برای نتایج اسکنر غول */
			try {
				const session = await DbService.getSession(request, env);
				if (!session || !session.is_admin) return new Response(JSON.stringify({ error: "دسترسی مجاز نیست" }), { status: 403, headers: { "Content-Type": "application/json; charset=utf-8" } });
				const body = await readJsonBody(request);
				const ips = (Array.isArray(body && body.ips) ? body.ips : []).map(function (x) { return String(x || "").trim(); }).filter(function (x) { return /^\d{1,3}(\.\d{1,3}){3}$/.test(x); }).slice(0, 120);
				const cc = ips.length ? await sabiGeoBatch(ips, env) : {};
				const flags = {};
				for (const k in cc) flags[k] = sabiFlagEmoji(cc[k]);
				return new Response(JSON.stringify({ success: true, cc: cc, flags: flags }), { headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });
			} catch (e) {
				return new Response(JSON.stringify({ success: false, cc: {}, flags: {} }), { headers: { "Content-Type": "application/json; charset=utf-8" } });
			}
		}
		if (url.pathname === "/api/test-ips" && request.method === "POST") {
			try {
				const session = await DbService.getSession(request, env);
				if (!session || !session.is_admin) return new Response(JSON.stringify({ error: "دسترسی مجاز نیست" }), { status: 403, headers: { "Content-Type": "application/json; charset=utf-8" } });
				const body = await readJsonBody(request);
				const sniHost = await sabiPanelHostResolve(env, url.hostname);
				try { await sabiCfRangesRefresh(); } catch (e) { }
				const rawList = Array.isArray(body.ips) ? body.ips : String(body.ips || "").split(/[\s,]+/);
				const portT = [443, 2053, 2083, 2087, 2096, 8443].indexOf(String(body.port)) >= 0 ? Number(body.port) : 443;
				const ips = [];
				const seenT = {};
				rawList.forEach(function (x) {
					x = String(x || "").trim();
					if ((/^\d{1,3}(\.\d{1,3}){3}$/.test(x) || sabiIsIPv6(x)) && !seenT[x] && ips.length < 40) { seenT[x] = 1; ips.push(x); }
				});
				if (!ips.length) return new Response(JSON.stringify({ success: true, host: sniHost, results: [] }), { headers: { "Content-Type": "application/json; charset=utf-8" } });
				/* GIANT: لایهٔ BGP جهانی — فضای کلودفلر فوری ✅ بدون پروب بی‌فایده از داخل ورکر */
				let bgpListT = [];
				try { bgpListT = await sabiBgpCfRanges(env); } catch (e) { }
				const results = [];
				const BATCH = 8;
				for (let i = 0; i < ips.length; i += BATCH) {
					const slice = ips.slice(i, i + BATCH);
					const rs = await Promise.all(slice.map(async function (ip) {
						let p;
						const wideT = sabiIpInCfWide(ip, bgpListT);
						if (wideT) {
							p = { ok: true, ms: 0, reason: (wideT === "official" ? "لبهٔ رسمی کلودفلر" : "فضای کلودفلر (BGP جهانی AS13335)") + " — از سمت شبکهٔ کلودفلر زنده است؛ باز بودنش از اینترنت خودت با «تست از نت من» سنجیده می‌شود" };
						} else {
							p = await sabiProbeIpTls(ip, portT, sniHost, 4500);
							if (p.ok) p.reason = "از دیتاسنتر کلودفلر پاسخ داد (handshake TLS موفق) — یعنی آی‌پی زنده است، نه اینکه از اینترنت ایران باز است";
						}
						/* HONEST-TEST: این سمتِ «سرور» است، پس هیچ‌وقت ادعای ✅ کاربردی نمی‌کند؛
						   ملاک واقعی، پروب مرورگری از اینترنت خودِ مدیر است (side:"client").
						   ok همیشه ۱ می‌ماند تا هیچ آی‌پی قرمز/حذف نشود. */
						const reasonF = p.ok ? p.reason : "از سمت ورکر پاسخ گرفته نشد — آی‌پی قبول است و در کانفیگ‌ها می‌ماند";
						return { ip: ip, ok: 1, srv: p.ok ? 1 : 0, side: "server", ms: p.ms, reason: reasonF, cc: "" };
					}));
					rs.forEach(function (r) { results.push(r); });
				}
				try {
					const ccMapT = await sabiGeoBatch(results.map(function (r) { return r.ip; }));
					results.forEach(function (r) { r.cc = ccMapT[r.ip] || ""; });
				} catch (e) { }
				await sabiSaveIpTestResults(results, env);
				return new Response(JSON.stringify({ success: true, host: sniHost, results: results }), { headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });
			} catch (e) {
				return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { "Content-Type": "application/json" } });
			}
		}
