				/* ---- IP-FREE: بدون بررسی رنج — همه‌ی آی‌پی‌های کاربر بدون خطا پذیرفته می‌شوند ---- */
				const scanHost = url.hostname;
				const coloNow = String((request.cf && request.cf.colo) || "");
