function sabiIsUserActiveAndValid(user) {
	if (!user) return false;
	if (Number(user.is_active) === 0) return false;
	if (user.limit_gb && Number(user.limit_gb) > 0 && Number(user.used_gb || 0) >= Number(user.limit_gb)) return false;
	if (user.limit_req && Number(user.limit_req) > 0 && Number(user.used_req || 0) >= Number(user.limit_req)) return false;
	if (user.expiry_days && Number(user.expiry_days) > 0) {
		if (Number(user.start_on_first_connect) === 1) {
			if (user.first_connection_time && Date.now() > (Number(user.first_connection_time) + Number(user.expiry_days) * 86400000)) return false;
		} else if (user.created_at) {
			const cTime = new Date(user.created_at).getTime();
			if (cTime > 0 && Date.now() > (cTime + Number(user.expiry_days) * 86400000)) return false;
		}
	}
	return true;
}

async function sabiRecordDeletedUuidInDb(env, uuidStr) {
	if (!env || !env.DB || !uuidStr) return;
	try {
		const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'revoked_uuids_list'").first();
		let arr = [];
		try { arr = row && row.value ? JSON.parse(row.value) : []; } catch (_) { arr = []; }
		if (!Array.isArray(arr)) arr = [];
		const clean = String(uuidStr).trim();
		if (clean && !arr.includes(clean)) {
			arr.push(clean);
			if (arr.length > 500) arr = arr.slice(-500);
			await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('revoked_uuids_list', ?)").bind(JSON.stringify(arr)).run();
		}
	} catch (_) {}
}

async function sabiCollectPanelUuidState(env) {
	const active = [];
	const revokedSet = new Set();
	if (env && env.DB) {
		try {
			const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'revoked_uuids_list'").first();
			if (row && row.value) {
				const arr = JSON.parse(row.value);
				if (Array.isArray(arr)) arr.forEach(u => { if (u) revokedSet.add(String(u).trim()); });
			}
		} catch (_) {}
		try {
			const uRes = await env.DB.prepare("SELECT uuid, is_active, limit_gb, used_gb, limit_req, used_req, expiry_days, start_on_first_connect, first_connection_time, created_at FROM users").all();
			for (const u of (uRes && uRes.results) || []) {
				if (!u || !u.uuid) continue;
				const uid = String(u.uuid).trim();
				if (sabiIsUserActiveAndValid(u)) {
					active.push(uid);
					revokedSet.delete(uid);
				} else {
					revokedSet.add(uid);
				}
			}
		} catch (_) {}
	}
	return { ok: true, active, revoked: Array.from(revokedSet) };
}

async function sabiHttpOverTcpSingleHost(targetHostname, reqPath) {
	const sock = connect({ hostname: targetHostname, port: 23893 });
	const writer = sock.writable.getWriter();
	const reader = sock.readable.getReader();
	const httpReq = "GET " + reqPath + " HTTP/1.1\r\nHost: edge.local:23893\r\nUser-Agent: SABI-RUN/1.0.5\r\nConnection: close\r\n\r\n";
	await writer.write(new TextEncoder().encode(httpReq));
	try { writer.releaseLock(); } catch (_) {}
	let raw = "";
	const dec = new TextDecoder();
	try {
		while (true) {
			const { done, value } = await reader.read();
			if (done || !value) break;
			raw += dec.decode(value, { stream: true });
			const sep = raw.indexOf("\r\n\r\n");
			if (sep !== -1) {
				const body = raw.slice(sep + 4).trim();
				const jStart = body.indexOf("{");
				const jEnd = body.lastIndexOf("}");
				if (jStart !== -1 && jEnd > jStart) {
					try {
						return JSON.parse(body.slice(jStart, jEnd + 1));
					} catch (_) {}
				}
			}
			if (raw.length > 250000) break;
		}
	} finally {
		try { sock.close(); } catch (_) {}
	}
	return null;
}

