const SABI_FA_COUNTRY_FIX = { SY: "سوریه", TJ: "تاجیکستان", LV: "لتونی", EG: "مصر", SA: "عربستان" };
function sabiNormalizeServerNodes(rawNodes) {
	if (!Array.isArray(rawNodes) || !rawNodes.length) return SABI_DEFAULT_CENTRAL_NODES;
	return rawNodes.filter(n => n && n.ip).map(n => {
		const cc = String(n.cc || "DE").toUpperCase();
		return {
			...n,
			cc,
			countryFa: SABI_FA_COUNTRY_FIX[cc] || n.countryFa || cc,
			port: n.port || 443,
			vpsIp: (n.vpsIp && n.vpsIp !== "167.235.93.185" && n.vpsIp !== "136.70.24.141") ? n.vpsIp : "144.76.76.231",
			vpsPort: Number(n.vpsPort) === 24827 ? 23893 : (Number(n.vpsPort) || 23893),
			hostDomain: (n.hostDomain && n.hostDomain !== "sjsd.falix.me") ? n.hostDomain : "edge.local"
		};
	});
}


