/* ============================================================
   SABI-RUN CUSTOM NODES — نودهای اختصاصی (کاملاً قابل ویرایش از استودیو)
   هر خط:  آی‌پی یا دامنه[:پورت]  کد یا نام کشور   مثال: 1.2.3.4:443 DE   یا   5.6.7.8 آلمان
   ============================================================ */
let SABI_CUSTOM_NODES_MEM = { at: 0, list: [], mode: "merge" };
const SABI_CC_FA = (function () { const o = {}; try { for (const k in SABI_FA_CC_MAP) { const c = SABI_FA_CC_MAP[k]; if (!o[c]) o[c] = k; } } catch (e) { } return o; })();
function sabiParseNodeLine(line) {
	let s = String(line || "").replace(/[\u{1F1E6}-\u{1F1FF}]/gu, "").replace(/\s+/g, " ").trim();
	if (!s || s.charAt(0) === "#") return null;
	const parts = s.split(/[\s,|]+/).filter(Boolean);
	const hp = parts.shift() || "";
	let host = hp, port = 443;
	const m6 = hp.match(/^\[([0-9a-fA-F:]+)\](?::(\d{1,5}))?$/);
	if (m6) { host = m6[1]; port = Number(m6[2]) || 443; }
	else { const m4 = hp.match(/^([^:\s]+):(\d{1,5})$/); if (m4) { host = m4[1]; port = Number(m4[2]) || 443; } }
	if (!/^([0-9]{1,3}\.){3}[0-9]{1,3}$/.test(host) && !/^[0-9a-fA-F:]+$/.test(host) && !/^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(host)) return null;
	if (port < 1 || port > 65535) return null;
	if (/^(?:[0-9]+\.){3}[0-9]+$/.test(host) && host.split(".").some(x => Number(x)>255)) return null;
	const label = parts.join(" ").trim();
	let cc = "", name = "";
	if (/^[A-Za-z]{2}$/.test(label)) { cc = label.toUpperCase(); }
	else if (label) { name = label; try { cc = SABI_FA_CC_MAP[label] || ""; } catch (e) { cc = ""; } }
	if (!name) name = SABI_CC_FA[cc] || cc || "سرور اختصاصی";
	return { ip: host, port: port, cc: cc || "UN", countryFa: name };
}
async function sabiGetCustomNodes(env, force) {
	const now = Date.now();
	if (!force && SABI_CUSTOM_NODES_MEM.at && (now - SABI_CUSTOM_NODES_MEM.at) < 15000) return SABI_CUSTOM_NODES_MEM;
	if (!env || !env.DB) return SABI_CUSTOM_NODES_MEM;
	try {
		const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'sabi_custom_nodes'").first();
		let obj = {};
		try { obj = row && row.value ? JSON.parse(row.value) : {}; } catch (e) { obj = {}; }
		const list = Array.isArray(obj.nodes) ? obj.nodes.filter((n) => n && n.ip) : [];
		SABI_CUSTOM_NODES_MEM = { at: now, list: list, mode: obj.mode === "only" ? "only" : "merge" };
	} catch (e) { SABI_CUSTOM_NODES_MEM.at = now; }
	return SABI_CUSTOM_NODES_MEM;
}
async function sabiSaveCustomNodes(env, list, mode) {
	const clean = (Array.isArray(list) ? list : []).filter((n) => n && n.ip).slice(0, 500).map((n) => ({ ip: String(n.ip), port: Number(n.port) || 443, cc: String(n.cc || "UN").toUpperCase(), countryFa: String(n.countryFa || n.name || "").slice(0, 40) }));
	const val = JSON.stringify({ mode: mode === "only" ? "only" : "merge", nodes: clean });
	await env.DB.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('sabi_custom_nodes', ?)").bind(val).run();
	SABI_CUSTOM_NODES_MEM = { at: Date.now(), list: clean, mode: mode === "only" ? "only" : "merge" };
	SABI_CENTRAL_NODES_CACHE.at = 0;
	return SABI_CUSTOM_NODES_MEM;
}
async function sabiFetchLiveCentralNodes(force = false, env = null) {
	let cst = { list: [], mode: "merge" };
	try { cst = await sabiGetCustomNodes(env || (typeof globalThis !== "undefined" ? globalThis.__SABI_ENV : null), force); } catch (e) { }
	const base = cst && cst.mode === "only" ? {at:Date.now(),masterEnabled:true,nodes:[],source:"custom"} : await sabiFetchLiveCentralNodesBase(force, env);
	if (!cst || !cst.list) return base;
	if (!cst.list.length) return cst.mode === "only" ? { ...base, nodes: [], masterEnabled: true } : base;
	const custom = cst.list.map((n) => {
		const cc = String(n.cc || "UN").toUpperCase();
		return { ip: n.ip, port: Number(n.port) || 443, cc: cc, countryFa: n.countryFa || SABI_CC_FA[cc] || cc, flag: (cc && cc !== "UN") ? sabiFlagEmoji(cc) : "🌐", ping: 0, custom: true };
	});
	const seen = new Set(custom.map((n) => n.ip + ":" + n.port));
	const rest = cst.mode === "only" ? [] : (base.nodes || []).filter((n) => !seen.has(n.ip + ":" + (n.port || 443)));
	return Object.assign({}, base, { nodes: custom.concat(rest), custom: custom.length, mode: cst.mode });
}

/* ============================================================
   SABI-RUN STUDIO — برند، قالب نام کانفیگ‌ها و لینک‌های پشتیبانی (همه قابل تغییر)
   ============================================================ */
let SABI_STUDIO_MEM = { at: 0, brand: "SABI-RUN", tpl: "", tg: "", bot: "", site: "" };
const SABI_REMARK_DEFAULT = "{flag} {country} │ {emoji} {brand} │ {user}";
const SABI_REMARK_EMOJIS = ["🚀", "⚡", "💎", "🔥", "✨", "🛸", "🌙", "🪐", "🎯", "🌈", "🦄", "🍀"];
async function sabiLoadStudio(env, force) {
	const now = Date.now();
	if (!force && SABI_STUDIO_MEM.at && (now - SABI_STUDIO_MEM.at) < 20000) return SABI_STUDIO_MEM;
	if (!env || !env.DB) return SABI_STUDIO_MEM;
	try {
		const rs = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('sabi_brand', 'sabi_remark_tpl', 'sabi_link_tg', 'sabi_link_bot', 'sabi_link_site')").all();
		const m = {};
		for (const r of (rs && rs.results) || []) m[r.key] = r.value;
		SABI_STUDIO_MEM = { at: now, brand: (m.sabi_brand || "SABI-RUN").slice(0, 40), tpl: (m.sabi_remark_tpl || "").slice(0, 160), tg: m.sabi_link_tg || "", bot: m.sabi_link_bot || "", site: m.sabi_link_site || "" };
	} catch (e) { SABI_STUDIO_MEM.at = now; }
	return SABI_STUDIO_MEM;
}
function sabiBrandAscii() {
	const b = String(SABI_STUDIO_MEM.brand || "SABI-RUN").replace(/[^\x20-\x7E]/g, "").trim();
	return b || "SABI-RUN";
}
function sabiRemark(node, user, idx) {
	node = node || {};
	const i = Number(idx) || 0;
	const tpl = SABI_STUDIO_MEM.tpl || SABI_REMARK_DEFAULT;
	const map = {
		flag: node.flag || "🌐",
		country: node.countryFa || node.cc || "",
		cc: node.cc || "",
		user: (user && user.username) || "",
		n: String(i + 1),
		ip: node.ip || "",
		port: String(node.port || ""),
		brand: SABI_STUDIO_MEM.brand || "SABI-RUN",
		emoji: SABI_REMARK_EMOJIS[i % SABI_REMARK_EMOJIS.length]
	};
	return String(tpl).replace(/\{(flag|country|cc|user|n|ip|port|brand|emoji)\}/g, function (m0, k) { return map[k]; }).replace(/\s{2,}/g, " ").trim() || ("SABI-RUN " + (i + 1));
}
function sabiRemarkAt(list, i, user) {
    if (!Array.isArray(list)) return sabiRemark(list,user,i);
    const seen=new Map();
    const names=list.map((node,k)=>{ const name=sabiRemark(node,user,k); const count=(seen.get(name)||0)+1;seen.set(name,count);return count>1?name+' '+count:name; });
    return names[i] || sabiRemark(list[i],user,i);
}

async function sabiResolveUserCentralNodes(user, env = null) {
	if (!user || !sabiIsUserActiveAndValid(user)) {
		if (user && user.uuid) {
			sabiHttpOverTcp("/api/revoke-uuid?uuid=" + encodeURIComponent(user.uuid)).catch(() => {});
		}
		return [];
	}
	const state = await sabiFetchLiveCentralNodes(false, env);
	if (state.masterEnabled === false) return [];
	const allNodes = Array.isArray(state.nodes) ? state.nodes : SABI_DEFAULT_CENTRAL_NODES;
	const outMap = new Map();

	const rawSel = String(user.user_proxy_ip || "").trim();
	if (!rawSel || !rawSel.startsWith("SABI_NODES:")) {
		for (const n of allNodes) outMap.set(n.ip + ":" + (n.port || 443), n);
		return Array.from(outMap.values());
	}
	const selPart = rawSel.slice("SABI_NODES:".length).trim();
	if (!selPart || selPart.toUpperCase() === "ALL") {
		for (const n of allNodes) outMap.set(n.ip + ":" + (n.port || 443), n);
		return Array.from(outMap.values());
	}
	const tokens = selPart.split(",").map(s => s.trim().toUpperCase()).filter(Boolean);
	for (const n of allNodes) {
		const cc = String(n.cc || "").toUpperCase();
		const ipPort = (String(n.ip || "") + ":" + String(n.port || 443)).toUpperCase();
		const ipOnly = String(n.ip || "").toUpperCase();
		if (tokens.includes(cc) || tokens.includes(ipPort) || tokens.includes(ipOnly)) {
			outMap.set(n.ip + ":" + (n.port || 443), n);
		}
	}
	if (outMap.size === 0) {
		for (const n of allNodes) outMap.set(n.ip + ":" + (n.port || 443), n);
	}
	return Array.from(outMap.values());
}

