function getUser(username) {
	for (var i = 0; i < State.allUsers.length; i++) if (State.allUsers[i].username === username) return State.allUsers[i];
	return null;
}
/* دامنه و origin پنل: اگر پنل را با آی‌پی باز کرده باشید، آی‌پی هرگز در لینک نمی‌آید */
function sabiPanelHostName() {
	return (window.SABI_RUN_HOST && window.SABI_RUN_HOST.length) ? window.SABI_RUN_HOST : window.location.hostname;
}
function sabiPanelOrigin() {
	var proto = (window.location.protocol === 'http:') ? 'http://' : 'https://';
	return proto + sabiPanelHostName();
}
function getSubLink(username) { return sabiPanelOrigin() + '/feed/' + encodeURIComponent(username); }
function getSubTextLink(username) { return sabiPanelOrigin() + '/sub/' + encodeURIComponent(username); }
function getSingboxLink(username) { return sabiPanelOrigin() + '/singbox/' + encodeURIComponent(username); }
function getV2JsonLink(username) { return sabiPanelOrigin() + '/v2json/' + encodeURIComponent(username); }
/* v1.0.5: صفحهٔ وضعیت اتصال حذف شد — هر لینک «وضعیت» همان پرتال کاربر است */
function getStatusLink(username) { return getPortalLink(username); }
function getPortalLink(username) { return sabiPanelOrigin() + '/s/' + encodeURIComponent(username); }
window.getSubLink = getSubLink;
window.getSingboxLink = getSingboxLink;
window.getV2JsonLink = getV2JsonLink;
window.getStatusLink = getStatusLink;

var SABI_HTTP_TWIN = { '443': '80', '2053': '2052', '2083': '2082', '2087': '2086', '2096': '2095', '8443': '8080' };
function getvIeesLink(username, fallbackUuid) {
	var user = getUser(username);
	if (!user && fallbackUuid) {
		user = { username: username, uuid: fallbackUuid, is_active: 1, user_proxy_ip: 'SABI_NODES:ALL' };
	}
	if (!user) return '';
	if (user.is_active !== undefined && Number(user.is_active) === 0) {
		return 'vless://00000000-0000-0000-0000-000000000000@127.0.0.1:1?encryption=none&security=none&type=ws#' + encodeURIComponent('⛔ کاربر غیرفعال است (' + user.username + ')');
	}
	var allNodes = (window.SABI_CLIENT_NODES && window.SABI_CLIENT_NODES.length) ? window.SABI_CLIENT_NODES : [];
	var outMap = {};
	var outList = [];

	// فقط کشورهای آی‌پی ثابت سرور مرکزی آی‌پی ثابت (بدون ساخت هیچ کانفیگ آذربایجان یا pages.dev و بدون آی‌پی دستی)
	var rawSel = String(user.user_proxy_ip || '').trim();
	var tokens = [];
	var useAll = true;
	if (rawSel.indexOf('SABI_NODES:') === 0) {
		var sp = rawSel.slice('SABI_NODES:'.length).trim();
		if (sp && sp.toUpperCase() !== 'ALL') {
			useAll = false;
			tokens = sp.split(',').map(function (x) { return x.trim().toUpperCase(); }).filter(Boolean);
		}
	}
	for (var ni = 0; ni < allNodes.length; ni++) {
		var nd = allNodes[ni];
		var ccUp = String(nd.cc || '').toUpperCase();
		var ipUp = String(nd.ip || '').toUpperCase();
		var ipPortUp = ipUp + ':' + (nd.port || 443);
		if (useAll || tokens.indexOf(ccUp) >= 0 || tokens.indexOf(ipUp) >= 0 || tokens.indexOf(ipPortUp) >= 0) {
			var nk = nd.ip + ':' + (nd.port || 443);
			if (!outMap[nk]) {
				outMap[nk] = true;
				outList.push(nd);
			}
		}
	}
	if (outList.length === 0) outList = allNodes.slice();

	var links = [];
	var panelHost = window.location.hostname;
	for (var i = 0; i < outList.length; i++) {
		var node = outList[i];
		var nodeIp = node.ip;
		var nodePort = Number(node.port) || 443;
		var wsPath = encodeURIComponent('/ws?ip=' + nodeIp + ':' + nodePort);
		var nameParts = {flag:node.flag||'🌐',country:node.countryFa||node.cc||'',cc:node.cc||'',emoji:['🚀','⚡','💎','🔥','✨','🛸','🌙','🪐'][i%8],brand:window.SABI_BRAND||'SABI-RUN',user:user.username||'',n:String(i+1),ip:nodeIp,port:String(nodePort)};
        var remark = String(window.SABI_REMARK_TPL || '{flag} {country} │ {emoji} {brand} │ {user}').replace(/\\{(flag|country|cc|emoji|brand|user|n|ip|port)\\}/g,function(m,k){return nameParts[k];});
		var encRemark = encodeURIComponent(remark).replace(/\\(/g, '%28').replace(/\\)/g, '%29');
		links.push('vless://' + (user.uuid || '') + '@' + nodeIp + ':' + nodePort + '?encryption=none&security=tls&sni=' + panelHost + '&fp=chrome&alpn=http%2F1.1&type=ws&host=' + panelHost + '&path=' + wsPath + '#' + encRemark);
	}
	return links.join('\\n');
}
window.getvIeesLink = getvIeesLink;
setTimeout(function () { try { if (window.sabiLoadCentralCountries) window.sabiLoadCentralCountries(false); } catch (e) {} }, 350);

