	if (!txt.replace(/\s/g, '')) {
		var sub = '';
		try { sub = getSubLink(username); } catch (e) { sub = ''; }
		if (sub) { sabiCopy(sub, '\u26a0\ufe0f \u0644\u06cc\u0646\u06a9 \u0633\u0627\u0628 \u06a9\u067e\u06cc \u0634\u062f!'); return; }
		sabiToastSafe('\u26a0\ufe0f \u06a9\u0627\u0646\u0641\u06cc\u06af\u06cc \u0633\u0627\u062e\u062a\u0647 \u0646\u0634\u062f\u061b \u0635\u0641\u062d\u0647 \u0631\u0627 \u0631\u0641\u0631\u0634 \u06a9\u0646\u06cc\u062f.', 'warn');
		return;
	}
	sabiCopy(txt, '✅ کانفیگ کپی شد!');
