window.sabiSyncSelectedCountriesToInput = function () {
	var hiddenInput = $('fUserProxyIp');
	if (!hiddenInput) return;
	var allCount = (window.SABI_CLIENT_NODES || []).length;
	if (!window.SABI_SELECTED_CCS || window.SABI_SELECTED_CCS.length === 0) {
		hiddenInput.value = 'SABI_NODES:ALL';
	} else if (allCount > 0 && window.SABI_SELECTED_CCS.length >= allCount) {
		hiddenInput.value = 'SABI_NODES:ALL';
	} else {
		hiddenInput.value = 'SABI_NODES:' + window.SABI_SELECTED_CCS.join(',');
	}
	/* v2.0.0-FIX: انتخاب کشور دیگر بهینه‌ساز را خاموش نمی‌کند */
	var sumEl = $('sabiSelectedCountriesSummary');
	if (sumEl) {
		var countShown = (!window.SABI_SELECTED_CCS || window.SABI_SELECTED_CCS.length === 0) ? allCount : window.SABI_SELECTED_CCS.length;
		sumEl.innerHTML = '🟢 <b>' + countShown + ' آی‌پی ثابت اختصاصی کشورها</b> فعال است.';
	}
};

window.sabiRenderCountryNodesGrid = function () {
	var grid = $('sabiCountryNodesGrid');
	if (!grid) return;
	var list = window.SABI_CLIENT_NODES || [];
	var sel = window.SABI_SELECTED_CCS || [];
	grid.innerHTML = list.map(function (n) {
		var key = String(n.ip || n.cc).toUpperCase();
		var ccUp = String(n.cc || '').toUpperCase();
		var isSel = sel.indexOf('ALL') >= 0 || sel.indexOf(key) >= 0 || sel.indexOf(ccUp) >= 0;
		var ccLow = String(n.cc || 'de').toLowerCase();
		var flagUrl = n.flagImg || ('https://flagcdn.com/w40/' + ccLow + '.png');
		var borderCol = isSel ? '#10b981' : 'rgba(148,163,184,.22)';
		var bgCol = isSel ? 'rgba(16,185,129,.15)' : 'rgba(15,23,42,.55)';
		return '<div data-cc="' + key + '" onclick="window.sabiToggleCountryNode(this.dataset.cc)" style="cursor:pointer;user-select:none;border:1.5px solid ' + borderCol + ';background:' + bgCol + ';border-radius:12px;padding:10px 11px;display:flex;flex-direction:column;gap:6px;transition:all .14s">' +
			'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px">' +
				'<div style="display:flex;align-items:center;gap:7px;font-weight:800;font-size:13px">' +
					'<img src="' + flagUrl + '" alt="' + key + '" style="width:24px;height:16px;border-radius:3px;object-fit:cover;border:1px solid rgba(255,255,255,.2)" onerror="this.hidden=true">' +
					'<span>' + (n.countryFa || n.cc) + '</span>' +
				'</div>' +
				'<span style="font-size:11px;font-weight:900;padding:2px 7px;border-radius:99px;background:' + (isSel ? '#10b981' : 'rgba(148,163,184,.15)') + ';color:' + (isSel ? '#04130d' : '#94a3b8') + '">' + (isSel ? '✓ فعال' : 'انتخاب') + '</span>' +
			'</div>' +
			'<div style="display:flex;align-items:center;justify-content:space-between;font-size:11px;opacity:.82;font-family:monospace;direction:ltr">' +
				'<span>' + n.ip + '</span>' +
				'<span style="color:#38bdf8">⚡ ' + (n.ping || 77) + ' ms</span>' +
			'</div>' +
		'</div>';
	}).join('');
	window.sabiSyncSelectedCountriesToInput();
};

window.sabiToggleCountryNode = function (key) {
	key = String(key || '').toUpperCase();
	if (window.SABI_SELECTED_CCS.indexOf('ALL') >= 0) {
		window.SABI_SELECTED_CCS = (window.SABI_CLIENT_NODES || []).map(function (n) { return String(n.ip || n.cc).toUpperCase(); });
	}
	var idx = window.SABI_SELECTED_CCS.indexOf(key);
	if (idx >= 0) window.SABI_SELECTED_CCS.splice(idx, 1);
	else window.SABI_SELECTED_CCS.push(key);
	window.sabiRenderCountryNodesGrid();
};

window.sabiSelectAllCountries = function (selectAll) {
	if (selectAll) {
		window.SABI_SELECTED_CCS = (window.SABI_CLIENT_NODES || []).map(function (n) { return String(n.ip || n.cc).toUpperCase(); });
	} else {
		window.SABI_SELECTED_CCS = [];
	}
	window.sabiRenderCountryNodesGrid();
};

window.sabiLoadCentralCountries = function (force) {
	return api('/api/central-nodes' + (force ? '?force=1' : ''))
		.then(function (r) { return r.json(); })
		.then(function (d) {
			if (d && Array.isArray(d.nodes) && d.nodes.length) {
				window.SABI_CLIENT_NODES = d.nodes;
				if (window.SABI_SELECTED_CCS.indexOf('ALL') >= 0) {
					window.SABI_SELECTED_CCS = d.nodes.map(function (n) { return String(n.ip || n.cc).toUpperCase(); });
				}
				window.sabiRenderCountryNodesGrid();
				try {
					if ($('kvIpLoaded')) $('kvIpLoaded').textContent = String(d.nodes.length);
					if ($('kvIpTime')) $('kvIpTime').textContent = 'بروزرسانی خودکار';
					if (typeof filterAndRenderUsers === 'function' && State.allUsers && State.allUsers.length) filterAndRenderUsers();
				} catch (e) {}
				if (force) toast('✅ ' + d.nodes.length + ' آی‌پی ثابت کشورها بروزرسانی شد!', 'ok');
			}
		})
		.catch(function () {
			window.sabiRenderCountryNodesGrid();
		});
};

window.sabiQuickAddCentralIp = function () {
	if (typeof window.sabiOpenStudio === 'function') { window.sabiOpenStudio('nodes'); return; }
	toast('برای افزودن آی‌پی اختصاصی، استودیو را از نوار بالا باز کنید.', 'info');
};

window.sabiInitUserCountriesModal = function (rawProxyIpVal) {
	var raw = String(rawProxyIpVal || '').trim();
	window.SABI_SELECTED_CCS = [];
	if (!raw || raw === 'SABI_NODES:ALL') {
		window.SABI_SELECTED_CCS = (window.SABI_CLIENT_NODES || []).map(function (n) { return String(n.ip || n.cc).toUpperCase(); });
	} else if (raw.indexOf('SABI_NODES:') === 0) {
		var part = raw.slice('SABI_NODES:'.length).trim();
		if (part.toUpperCase() === 'ALL') {
			window.SABI_SELECTED_CCS = (window.SABI_CLIENT_NODES || []).map(function (n) { return String(n.ip || n.cc).toUpperCase(); });
		} else if (part) {
			window.SABI_SELECTED_CCS = part.split(',').map(function (x) { return x.trim().toUpperCase(); }).filter(Boolean);
		}
	}
	window.sabiRenderCountryNodesGrid();
	window.sabiLoadCentralCountries(false);
};

