/* ============================================================
   v1.0.5 — مخزن ProxyIP: چند منبع بزرگ + تست واقعی از سمت سرور
   (handshake TLS با SNI کلودفلری؛ هرکس گواهی درست برگرداند سالم است)
   ============================================================ */
var SABI_PROXYIP_STATE = { list: [], current: '', at: 0 };
function sabiProxyIpPaint(box, note) {
	if (!box) return;
	var list = SABI_PROXYIP_STATE.list || [];
	var good = list.filter(function (x) { return x.ok; });
	var html = '';
	if (note) html += '<div style="padding:6px 0;opacity:.9">' + esc(note) + '</div>';
	if (!list.length && !note) { html = '<div style="padding:8px 0;opacity:.85">هنوز نتیجه‌ای نیست — «تست زنده» را بزن.</div>'; }
	if (list.length) {
		html += '<div style="display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:11.5px;opacity:.85">' +
			'<span>✅ سالم: <b>' + good.length + '</b> از ' + list.length + '</span>' +
			'<span>ProxyIP فعلی: <b class="mono">' + esc(SABI_PROXYIP_STATE.current || '—') + '</b></span></div>';
		html += '<div style="display:grid;gap:5px;max-height:320px;overflow:auto">';
		for (var i = 0; i < list.length; i++) {
			var p = list[i];
			var isCur = (String(SABI_PROXYIP_STATE.current || '').split(',').indexOf(p.host) >= 0);
			html += '<div style="display:flex;align-items:center;gap:8px;border:1px solid ' + (p.ok ? 'rgba(16,185,129,.3)' : 'rgba(148,163,184,.15)') + ';border-radius:10px;padding:6px 9px;opacity:' + (p.ok ? '1' : '.6') + '">' +
				'<span style="flex:0 0 auto">' + (p.ok ? '✅' : '🚫') + '</span>' +
				'<span style="flex:0 0 auto">' + flagHtml(p.cc || '') + '</span>' +
				'<code class="mono" style="flex:1;font-size:11.5px;word-break:break-all" dir="ltr">' + esc(p.host) + (p.port && p.port !== 443 ? ':' + p.port : '') + '</code>' +
				'<span style="font-size:11px;opacity:.8;flex:0 0 auto">' + esc(p.ok ? (p.ms + 'ms') : (p.reason || 'بدون پاسخ')) + '</span>' +
				(p.ok ? '<button type="button" class="btn btn-sm" data-pipick="' + attr(p.host) + '">' + (isCur ? '✓ فعلی' : 'انتخاب') + '</button>' : '') +
				'</div>';
		}
		html += '</div>';
	}
	box.innerHTML = html;
	var btns = box.querySelectorAll('[data-pipick]');
	for (var j = 0; j < btns.length; j++) {
		(function (b) {
			on(b, 'click', function () { sabiProxyIpApply(b.getAttribute('data-pipick')); });
		})(btns[j]);
	}
}
async function sabiProxyIpFetch(force) {
	var box = $('proxyIpList');
	sabiProxyIpPaint(box, force ? '⏳ در حال تست زندهٔ ProxyIPها از سمت سرور (چند منبع بزرگ + لیست داخلی)... ممکن است ۲۰ تا ۴۰ ثانیه طول بکشد.' : '⏳ در حال خواندن مخزن...');
	try {
		var res = await (force ? api('/api/proxyip-repo', { body: { auto_apply: false } }) : api('/api/proxyip-repo'));
		var d = await res.json().catch(function () { return {}; });
		SABI_PROXYIP_STATE = { list: (d && d.list) || [], current: (d && d.current) || '', at: Date.now() };
		var good = SABI_PROXYIP_STATE.list.filter(function (x) { return x.ok; }).length;
		sabiProxyIpPaint(box, (d && d.error) ? ('⚠️ ' + d.error) : (good ? ('✅ ' + good + ' ProxyIP سالم پیدا شد — سریع‌ترین بالا است. روی «انتخاب» بزن.') : '🚫 هیچ ProxyIP سالمی پاسخ نداد — «تست زنده» را دوباره بزن یا دامنهٔ ProxyIP خودت را وارد کن.'));
	} catch (e) {
		sabiProxyIpPaint(box, '❌ خطا: ' + String((e && e.message) || e).slice(0, 140));
	}
}
async function sabiProxyIpApply(host) {
	host = String(host || '').trim();
	if (!host) return;
	try {
		var res = await api('/api/proxyip-repo', { body: { value: host } });
		var d = await res.json().catch(function () { return {}; });
		SABI_PROXYIP_STATE.current = (d && d.applied) || host;
		var si = $('setProxyIp');
		if (si) si.value = SABI_PROXYIP_STATE.current;
		sabiProxyIpPaint($('proxyIpList'));
		toast('✅ ProxyIP سراسری شد: ' + SABI_PROXYIP_STATE.current + ' — همهٔ اتصال‌ها از همین مسیر می‌روند', 'ok', 8000);
	} catch (e) { toast('❌ ذخیرهٔ ProxyIP ناموفق بود', 'err'); }
}
function sabiProxyIpOpenModal(targetFieldId) {
	var body = '<div style="line-height:1.9">' +
		'<div class="note"><svg><use href="#i-info"/></svg><div><b>ProxyIP</b> جای ساکس پروکسی عمومی را می‌گیرد: <b>سریع‌تر</b> (بدون handshake اضافه)، <b>پایدارتر</b> و مشکل مقاصد پشت کلودفلر (خطای 1033) را حل می‌کند. اینجا از <b>چند منبع بزرگ</b> + لیست داخلی جمع می‌شوند و <b>واقعی تست</b> می‌شوند (handshake TLS با SNI کلودفلری — هرکدام گواهی درست برگرداند سالم است) و بر اساس <b>پینگ</b> مرتب می‌شوند.</div></div>' +
		'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">' +
		'<button type="button" class="btn btn-sm btn-primary" id="btnPipForce">⚡ تست زنده و رتبه‌بندی</button>' +
		'<button type="button" class="btn btn-sm" id="btnPipAuto">🪄 انتخاب خودکار ۳ تای برتر</button>' +
		'</div>' +
		'<div id="proxyIpList" class="sabi-ip-status"></div>' +
		'</div>';
	genericModal({
		title: '🛰️ مخزن ProxyIP',
		sub: 'چند منبع بزرگ · تست واقعی · مرتب بر اساس پینگ',
		icon: 'globe',
		body: body,
		buttons: [{ primary: true, icon: 'check', text: 'بستن' }]
	});
	setTimeout(function () {
		on($('btnPipForce'), 'click', function () { sabiProxyIpFetch(true); });
		on($('btnPipAuto'), 'click', async function () {
			toast('⏳ در حال تست و انتخاب خودکار ۳ ProxyIP برتر...', 'info', 4000);
			try {
				var res = await api('/api/proxyip-repo', { body: { auto_apply: true } });
				var d = await res.json().catch(function () { return {}; });
				SABI_PROXYIP_STATE = { list: (d && d.list) || [], current: (d && d.current) || '', at: Date.now() };
				var si = $('setProxyIp');
				if (si && SABI_PROXYIP_STATE.current) si.value = SABI_PROXYIP_STATE.current;
				sabiProxyIpPaint($('proxyIpList'), SABI_PROXYIP_STATE.current ? ('✅ اعمال شد: ' + SABI_PROXYIP_STATE.current) : '🚫 ProxyIP سالمی پیدا نشد.');
				if (SABI_PROXYIP_STATE.current) toast('✅ ProxyIP سراسری: ' + SABI_PROXYIP_STATE.current, 'ok', 8000);
			} catch (e) { toast('❌ خطا در ارتباط با سرور', 'err'); }
		});
		if (SABI_PROXYIP_STATE.list.length) sabiProxyIpPaint($('proxyIpList'));
		else sabiProxyIpFetch(false);
	}, 60);
}
window.sabiProxyIpOpenModal = sabiProxyIpOpenModal;
window.sabiProxyIpApply = sabiProxyIpApply;
