/* ---------- submit ---------- */
function setSubmitState(text, disabled) {
	var btn = $('userSubmitBtn');
	if (!btn) return;
	var t = $('userSubmitText');
	if (t) t.textContent = text;
	btn.disabled = !!disabled;
}
