/* ============================================================
   30. UPDATE / RESTART / SOURCE
   ============================================================ */
var UPDATE_REPO = 'sabi-karami/SABI-RUN';
var UPDATE_FILES = ['SABI-RUN.js', 'worker.js', 'index.js', 'main.js', 'src/worker.js', 'SABI-RUN.js', 'SABI-RUN.js.txt', 'worker', 'panel.js', 'SABI-RUN.js', 'dist/worker.js', 'src/index.js'];
var UPDATE_BRANCHES = ['main', 'master', 'dev', 'v1', 'release'];
var UPDATE_MIRRORS = ['https://raw.githubusercontent.com/', 'https://cdn.jsdelivr.net/gh/'];
var UPDATE_TIMEOUT_MS = 8000;
var UPDATE_MAX_FILES = 6;
var UPDATE_DISCOVERED = null;
var UPDATE_BRANCH = null;
var UPDATE_BUSY = false;

/* fetch with a hard timeout so one hanging host can never stall the panel */
function updateFetch(url, opts, ms) {
	return new Promise(function (resolve, reject) {
		var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
		var timer = setTimeout(function () {
			if (ctl) { try { ctl.abort(); } catch (e) { } }
			reject(new Error('timeout'));
		}, ms || UPDATE_TIMEOUT_MS);
		var o = opts || {};
		if (ctl) { try { o.signal = ctl.signal; } catch (e) { } }
		var p;
		try { p = fetch(url, o); } catch (e) { clearTimeout(timer); reject(e); return; }
		Promise.resolve(p).then(function (r) { clearTimeout(timer); resolve(r); },
			function (e) { clearTimeout(timer); reject(e); });
	});
}

/* Ask GitHub which .js files the repo really has - a renamed worker file
   must never break the updater. Never throws. */
async function discoverUpdateFiles(branch) {
	var out = [];
	try {
		var r = await updateFetch('https://api.github.com/repos/' + UPDATE_REPO + '/contents?ref=' + encodeURIComponent(branch),
			{ cache: 'no-store', headers: { 'User-Agent': 'Mozilla/5.0', 'Accept': 'application/vnd.github+json' } }, 6000);
		if (!r || !r.ok) return out;
		var j = await r.json();
		if (!Array.isArray(j)) return out;
		j.forEach(function (it) {
			if (it && it.type === 'file' && /\.m?js$/i.test(it.path || '')) out.push(it.path);
		});
	} catch (e) { }
	return out;
}

/* Same two-tier rule as the worker side: GitHub first, CDN as fallback. */
function updateUrls(branch, files, stamp) {
	var raw = [];
	var cdn = [];
	files.forEach(function (f) {
		raw.push('https://raw.githubusercontent.com/' + UPDATE_REPO + '/' + branch + '/' + f + stamp);
		cdn.push('https://cdn.jsdelivr.net/gh/' + UPDATE_REPO + '@' + branch + '/' + f + stamp);
	});
	return { raw: raw, cdn: cdn };
}

/* Fire every candidate at once; the first real worker source wins. */
function raceUpdateSources(urls) {
	if (!urls.length) return Promise.resolve(null);
	return new Promise(function (resolve) {
		var left = urls.length, won = false;
		urls.forEach(function (u) {
			updateFetch(u, { cache: 'no-store', headers: { 'User-Agent': 'Mozilla/5.0' } }, UPDATE_TIMEOUT_MS)
				.then(function (r) {
					if (!r || !r.ok) return null;
					return r.text().then(function (t) {
						return (t && t.length > 20000 && t.indexOf('CURRENT_VERSION') >= 0) ? t : null;
					}, function () { return null; });
				})
				.catch(function () { return null; })
				.then(function (text) {
					left -= 1;
					if (text && !won) { won = true; resolve(text); }
					else if (left === 0 && !won) resolve(null);
				});
		});
	});
}

async function fetchUpdateSource() {
	if (UPDATE_BUSY) return null;
	UPDATE_BUSY = true;
	try {
		var stamp = '?t=' + Date.now();

		/* 1. learn the real file names once (a single cheap API call) */
		if (UPDATE_DISCOVERED === null) {
			UPDATE_DISCOVERED = [];
			for (var b = 0; b < UPDATE_BRANCHES.length; b++) {
				var found = await discoverUpdateFiles(UPDATE_BRANCHES[b]);
				if (found && found.length) { UPDATE_DISCOVERED = found; UPDATE_BRANCH = UPDATE_BRANCHES[b]; break; }
			}
		}

		/* 2. branch order: the branch we know exists first */
		var branches = [];
		if (UPDATE_BRANCH) branches.push(UPDATE_BRANCH);
		UPDATE_BRANCHES.forEach(function (br) { if (branches.indexOf(br) < 0) branches.push(br); });

		/* 3. candidates: discovered names first, then the well-known names */
		var files = UPDATE_DISCOVERED.concat(UPDATE_FILES)
			.filter(function (f, idx, arr) { return f && arr.indexOf(f) === idx; })
			.slice(0, UPDATE_MAX_FILES);

		/* 4. authoritative source first, cached CDN mirrors only as a fallback */
		for (var i = 0; i < branches.length && i < 3; i++) {
			var tiers = updateUrls(branches[i], files, stamp);
			var text = await raceUpdateSources(tiers.raw);
			if (!text) text = await raceUpdateSources(tiers.cdn);
			if (text) { UPDATE_BRANCH = branches[i]; return text; }
		}

		/* 5. منبع آپدیت فقط گیت‌هاب است — fallback دیگری وجود ندارد */
		return null;
	} finally {
		UPDATE_BUSY = false;
	}
}

window.fetchUpdateSource = fetchUpdateSource;

/* ============================================================
   SABI-RUN v1.0.5 — آپدیت خودکار از گیت‌هاب (با پرسش از مدیر)
   ============================================================ */
var SABI_UPDATE_PROMPT_AT = 0;
var SABI_UPDATE_PROMPT_VER = '';
var SABI_UPDATE_BUSY = false;

async function checkForUpdates(isManual) {
	try {
		var res = await api('/api/update-check');
		var info = await res.json().catch(function () { return {}; });
		if (!res.ok || !info || info.error) throw new Error((info && info.error) || 'check');
		State.latestVersion = info.latest || CURRENT_VERSION;
		set('setLatest', info.latest || '—');
		set('mLatest', info.latest || '—');
		renderUpdateState({ latest: info.latest, isNewer: !!info.has_update, error: false });
		if (info.has_update) {
			if (isManual) openUpdateModal(info.latest);
			else await promptUpdate(info.latest);
		} else if (isManual) {
			toast('✅ پنل به‌روز است (نسخه ' + (info.current || CURRENT_VERSION) + ')', 'ok');
		}
	} catch (e) {
		renderUpdateState({ error: true });
		if (isManual) toast('بررسی آپدیت ناموفق بود؛ اتصال به گیت‌هاب برقرار نشد.', 'warn');
	}
}
window.checkForUpdates = checkForUpdates;

/* v1.0.5: آپدیت مخفی حذف شد — پنل نسخهٔ جدید را «اعلان» می‌دهد و فقط با تأیید مدیر آپدیت می‌کند */
async function promptUpdate(latest) {
	var now = Date.now();
	if (SABI_UPDATE_PROMPT_VER === latest && (now - SABI_UPDATE_PROMPT_AT) < 6 * 3600 * 1000) return false;
	SABI_UPDATE_PROMPT_AT = now;
	SABI_UPDATE_PROMPT_VER = latest;
	var ok = await confirmBox('🔔 نسخهٔ جدید ' + latest + ' روی مخزن گیت‌هاب موجود است (نسخهٔ فعلی پنل: ' + CURRENT_VERSION + '). آپدیت انجام شود؟',
		{ title: 'بروزرسانی پنل از گیت‌هاب', okText: 'بله، آپدیت کن', cancelText: 'بعداً' });
	if (!ok) return false;
	return await applyPanelUpdate();
}
window.promptUpdate = promptUpdate;

/* اعمال واقعی آپدیت: سورس از گیت‌هاب گرفته و روی همین ورکر نوشته می‌شود */
async function applyPanelUpdate(token) {
	if (SABI_UPDATE_BUSY) { toast('یک آپدیت در حال انجام است؛ چند لحظه صبر کنید.', 'warn'); return false; }
	SABI_UPDATE_BUSY = true;
	try {
		closeModal('modalUpdate');
		toast('در حال دریافت و اعمال آپدیت از گیت‌هاب... لطفاً چند ثانیه صبر کنید.', 'info', 12000);
		var res = await api('/api/update-panel', { method: 'POST', body: token ? { cf_token: token } : {} });
		var data = await res.json().catch(function () { return {}; });
		if (res.status === 400 && (data.error === 'TOKEN_REQUIRED' || data.error === 'INVALID_TOKEN')) {
			State.pendingCoreAction = 'update';
			openModal('modalToken');
			return false;
		}
		if (res.ok && data.success) {
			toast('✅ آپدیت با موفقیت اعمال شد. صفحه رفرش می‌شود...', 'ok', 9000);
			setTimeout(function () {
				try { sessionStorage.setItem('sabi_last_update', Date.now()); } catch (e) { }
				window.location.reload();
			}, 6000);
			return true;
		}
		toast('❌ آپدیت اعمال نشد: ' + ((data && data.error) || ('خطای ' + res.status)), 'err', 10000);
		return false;
	} catch (e) {
		toast('❌ خطا در ارتباط با سرور: ' + e.message, 'err', 9000);
		return false;
	} finally {
		SABI_UPDATE_BUSY = false;
	}
}
window.applyPanelUpdate = applyPanelUpdate;

/* ============================================================
   SABI-RUN IP-FREE — مرتب‌سازی آی‌پی‌ها: بدون بررسی رنج، بدون خطا
   ============================================================ */
async function sabiFilterIpsNow() {
	var st = $('sslTestStatus');
	var raw = ($('fIps') && $('fIps').value) || '';
	var ips = raw.replace(/[^0-9.]/g, ' ').split(' ').filter(function (x) {
		return /^[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}$/.test(x) && x.split('.').every(function (n) { return Number(n) <= 255; });
	});
	var seenIp = {};
	var uniq = [];
	ips.forEach(function (x) { if (!seenIp[x]) { seenIp[x] = 1; uniq.push(x); } });
	if (!uniq.length) { toast('آی‌پی‌ای وارد نشده است.', 'warn'); return; }
	$('fIps').value = uniq.join(String.fromCharCode(10));
	if (st) {
		st.style.display = '';
		st.textContent = uniq.length + ' آی‌پی آماده — همه پذیرفته شدند (بدون بررسی رنج)؛ کانفیگ TLS مستقیم با آی‌پی شما ساخته می‌شود';
	}
	toast('✅ ' + uniq.length + ' آی‌پی پذیرفته و مرتب شد.', 'ok');
}
window.sabiFilterIpsNow = sabiFilterIpsNow;
on($('btnFilterIps'), 'click', function () { sabiFilterIpsNow(); });

/* ============================================================
   HONEST IP TEST — «تست از نت خودم»
   ملاک، پروب واقعی از اینترنت خودِ مدیر است (همان منطق اسکنر غول):
     cert/open ⇒ لبه جواب داده ⇒ از نت تو باز است ✅
     rst       ⇒ ریست سریع اپراتور ⇒ فیلتر 🚫
     timeout   ⇒ هیچ پاسخی نیست ⇒ مسدود/مرده 🚫
   نتیجهٔ سمت سرور (handshake از دیتاسنتر کلودفلر) فقط به‌عنوان
   «زنده بودن آی‌پی» کنارش نمایش داده می‌شود و هرگز ✅ کاربردی نیست.
   هیچ آی‌پی حذف نمی‌شود — فیلد دست‌نخورده می‌ماند.
   ============================================================ */
function sabiNetVerdict(n) {
	if (!n || !n.done) return 'wait';
	if (n.cls === 'cert' || n.cls === 'open') return 'open';
	if (n.cls === 'rst' || n.cls === 'rst-late') return 'rst';
	return 'timeout';
}
async function sabiTestIpsNow(isAuto) {
	var st = $('sslTestStatus');
	var raw = ($('fIps') && $('fIps').value) || '';
	var ips = raw.replace(/[^0-9.]/g, ' ').split(' ').filter(function (x) {
		return /^[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}$/.test(x) && x.split('.').every(function (n) { return Number(n) <= 255; });
	});
	var uniq = [];
	ips.forEach(function (x) { if (uniq.indexOf(x) < 0) uniq.push(x); });
	uniq = uniq.slice(0, 60);
	if (!uniq.length) { if (!isAuto) toast('آی‌پی‌ای وارد نشده است.', 'warn'); return; }
	var btn = $('btnTestIps');
	if (btn) { btn.disabled = true; btn.innerHTML = '<svg><use href="#i-activity"/></svg>تست از نت خودت...'; }
	var rounds = isAuto ? 1 : 3;   /* v1.0.5: سه نمونه ⇒ پینگ میانهٔ پایدار */
	var net = {}, srv = {}, acc = {};
	uniq.forEach(function (ip) { net[ip] = { cls: '', ms: 0, done: false }; });
	var NOTE = '📡 ملاک، تست از اینترنت خودت است · نتیجهٔ سمت سرور فقط اطلاع‌رسانی است · هیچ آی‌پی حذف نمی‌شود';
	function paint() {
		if (!st) return;
		st.style.display = '';
		st.innerHTML = '';
		var nd = document.createElement('div');
		nd.style.cssText = 'padding:3px 0 6px;direction:rtl;text-align:right;opacity:.85';
		nd.textContent = NOTE;
		st.appendChild(nd);
		uniq.forEach(function (ip) {
			var n = net[ip], s = srv[ip], v = sabiNetVerdict(n);
			var head;
			if (v === 'wait') head = '⏳ ' + ip + ' — در حال تست از نت تو...';
			else if (v === 'open') head = '✅ ' + ip + ' — پینگ ' + (n.ms || '?') + 'ms' + (n.jit ? ' (جیتر ' + n.jit + ')' : '') + ' · ' + (n.samples || 1) + ' نمونه';
			else if (v === 'rst') head = '🚫 ' + ip + ' — از اینترنت تو بسته است (ریست اپراتور)';
			else head = '🚫 ' + ip + ' — از اینترنت تو پاسخ نمی‌دهد (timeout)';
			var tail = ' · سمت سرور: ' + (s ? (s.srv ? 'زنده' : 'بدون پاسخ') : '...') + (s && s.cc ? ' · ' + flagText(s.cc) : '') + ' · در کانفیگ می‌ماند';
			var div = document.createElement('div');
			div.style.cssText = 'padding:2px 0;direction:rtl;text-align:right';
			div.textContent = head + tail;
			st.appendChild(div);
		});
	}
	paint();
	try {
		/* کالیبراسیون آستانهٔ RST روی اینترنت فعلی مدیر */
		try { if (!GS.baseline) await gsCalibrate(); } catch (e) { }
		if (!GS.baseline) { GS.baseline = 150; GS.rstMax = 65; }
		var queue = [];
		for (var rd = 0; rd < rounds; rd++) uniq.forEach(function (ip) { queue.push(ip); });
		var qi = 0;
		async function runner() {
			while (qi < queue.length) {
				var ip = queue[qi++];
				var r = await gsProbeOnce(ip, 443, 3500);
				acc[ip] = acc[ip] || [];
				acc[ip].push(r);
				/* v1.0.5 — میانهٔ نمونه‌های موفق (نه کمینهٔ شانسی) + جیتر */
				var good = [];
				acc[ip].forEach(function (x) { if (x.cls === 'cert' || x.cls === 'open') good.push(x.ms); });
				good.sort(function (a, b) { return a - b; });
				var last = acc[ip][acc[ip].length - 1];
				var cls, ms, jit = 0;
				if (good.length) {
					cls = 'cert';
					ms = good[Math.floor(good.length / 2)];
					jit = good.length > 1 ? (good[good.length - 1] - good[0]) : 0;
				} else { cls = last.cls; ms = last.ms; }
				/* پاسخ «تمیز» که از پینگ پایهٔ خودِ پنل سریع‌تر است، ریست دیرهنگام اپراتور است */
				if (good.length && GS.baseline && ms < Math.max(45, GS.baseline * 0.55)) { cls = 'rst-late'; }
				net[ip] = { cls: cls, ms: ms, jit: jit, samples: good.length, done: acc[ip].length >= rounds };
				paint();
			}
		}
		var runners = [];
		var conc = Math.max(4, Math.min(10, uniq.length));
		for (var k = 0; k < conc; k++) runners.push(runner());
		var srvP = api('/api/test-ips', { method: 'POST', body: { ips: uniq, port: 443 } })
			.then(function (res) { return res.json(); })
			.then(function (d) { ((d && d.results) || []).forEach(function (r) { srv[r.ip] = r; }); paint(); })
			.catch(function () { });
		await Promise.all(runners.concat([srvP]));
		paint();
		var openN = uniq.filter(function (ip) { return sabiNetVerdict(net[ip]) === 'open'; }).length;
		var blockedN = uniq.length - openN;
		/* v1.0.5 — ترتیب آی‌پی‌ها بر اساس پینگ واقعی: سریع‌ترین اول می‌رود تا
		   کلاینت از همان اول به بهترین لبه وصل شود (هیچ آی‌پی حذف نمی‌شود) */
		if (!isAuto && $('fIps') && openN) {
			try {
				var order = uniq.slice().sort(function (a, b) {
					var na = net[a] || {}, nb = net[b] || {};
					var oa = sabiNetVerdict(na) === 'open' ? 0 : 1;
					var ob = sabiNetVerdict(nb) === 'open' ? 0 : 1;
					if (oa !== ob) return oa - ob;
					if (oa === 0) return (na.ms || 999999) - (nb.ms || 999999);
					return uniq.indexOf(a) - uniq.indexOf(b);
				});
				if (order.join(',') !== uniq.join(',')) {
					$('fIps').value = order.join(String.fromCharCode(10));
					sabiLastAutoTestedVal = $('fIps').value.trim();
					toast('↕️ آی‌پی‌ها بر اساس پینگ واقعی مرتب شدند (سریع‌ترین اول) — هیچ آی‌پی حذف نشد.', 'ok', 7000);
				}
			} catch (e) { }
		}
		if (!isAuto) {
			if (openN) toast('✅ ' + openN + ' آی‌پی از اینترنت تو باز است.', 'ok');
			if (blockedN) toast('🚫 ' + blockedN + ' آی‌پی از اینترنت تو بسته است — حذف نشد و در کانفیگ می‌ماند.', 'warn', 9000);
		}
	} catch (e) {
		if (st) { st.style.display = ''; st.textContent = 'تست ناموفق: ' + (e && e.message ? e.message : e); }
		if (!isAuto) toast('❌ تست آی‌پی ناموفق بود: ' + (e && e.message ? e.message : e), 'err', 9000);
	} finally {
		var btn2 = $('btnTestIps');
		if (btn2) { btn2.disabled = false; btn2.innerHTML = '<svg><use href="#i-activity"/></svg>تست از نت خودم'; }
	}
}
on($('btnTestIps'), 'click', function () { sabiTestIpsNow(); });
on($('btnOpenDomainIps'), 'click', function () { sabiOpenIpsModal(); });
window.sabiTestIpsNow = sabiTestIpsNow;
/* تست خودکار: وقتی آی‌پی وارد/ویرایش شد، بدون زدن دکمه تست می‌شود */
var sabiAutoTestTimer = null;
var sabiLastAutoTestedVal = null;
function sabiScheduleIpAutoTest() {
	if (sabiAutoTestTimer) clearTimeout(sabiAutoTestTimer);
	sabiAutoTestTimer = setTimeout(function () {
		var v = (($('fIps') && $('fIps').value) || '').trim();
		if (!v || v === sabiLastAutoTestedVal) return;
		sabiLastAutoTestedVal = v;
		sabiTestIpsNow(true);
	}, 900);
}
if ($('fIps')) { on($('fIps'), 'blur', sabiScheduleIpAutoTest); on($('fIps'), 'change', sabiScheduleIpAutoTest); }/* Draws the outcome of an update check into every place it can be seen, so
   the answer shows up wherever the button was pressed instead of only as a
   toast that disappears. */
function renderUpdateState(info) {
	info = info || {};
	var latest = info.latest || null;
	var isNewer = !!info.isNewer;
	var error = !!info.error;

	set('setLatest', error ? 'خطا' : (latest || '—'));
	set('mLatest', error ? 'خطا' : (latest || '—'));
	set('mAutoUpdate', State.autoUpdate ? 'فعال' : 'غیرفعال');

	var box;
	if (error) {
		box = '<div class="note err" style="margin-top:10px"><svg><use href="#i-alert"/></svg><div>' +
			'بررسی آپدیت ناموفق بود. اتصال به گیت‌هاب برقرار نشد - دوباره تلاش کنید.</div></div>';
	} else if (isNewer) {
		box = '<div class="note warn" style="margin-top:10px"><svg><use href="#i-alert"/></svg><div>' +
			'نسخه جدید <b class="mono">' + esc(latest) + '</b> در گیت‌هاب موجود است. نسخه فعلی شما <b class="mono">' + esc(CURRENT_VERSION) + '</b> است.' +
			'<br>برای اعمال خودکار، توکن کلودفلر با دسترسی ویرایش Worker لازم است.</div></div>';
	} else {
		box = '<div class="note ok" style="margin-top:10px"><svg><use href="#i-check"/></svg><div>' +
			'<b>نسخه ۱.۰.۵ (آخرین نسخه)</b> — پنل شما به آخرین نسخه مجهز است.<br>' +
			'<div style="margin-top:6px;font-size:12px;line-height:1.85;opacity:.92">' +
			'• 🌍 <b>آی‌پی‌های ثابت و زنده ۱۸ کشور</b> با سینک خودکار از سرور مرکزی (این آی‌پی‌ها بروز می‌شوند)<br>' +
			'• ⚡ <b>خروجی مستقیم روی سرور مرکزی</b> بدون افتادن روی pages.dev یا کانفیگ اضافی آذربایجان<br>' +
			'• 🛑 <b>قطع و حذف فوری کانفیگ از روی سرورها</b> به محض حذف یا غیرفعال شدن کاربر در پنل<br>' +
			'• 🧹 <b>حذف کامل Socks5 Proxy، ProxyIP و ثبت دستی آی‌پی</b> + خاموش شدن خودکار بهینه‌ساز' +
			'</div></div></div>';
	}
	['updateStatusSettings', 'updateStatusSystem'].forEach(function (id) {
		var el = $(id);
		if (!el) return;
		el.innerHTML = box;
		el.style.display = '';
	});
}
window.renderUpdateState = renderUpdateState;
